"use client";

import { createContext, useContext } from "react";
import type { ProductSummary } from "@/lib/catalog";

export interface CartItem {
  product: ProductSummary;
  quantity: number;
}

/**
 * What components rendered inside the conversation can do. A product card
 * generated by the model can add to the real cart or ask the assistant a
 * follow-up question: the UI and the chat drive each other.
 */
export interface ShopActions {
  cart: CartItem[];
  addToCart: (product: ProductSummary) => void;
  ask: (text: string) => void;
  busy: boolean;
}

export const ShopContext = createContext<ShopActions | null>(null);

export function useShop(): ShopActions {
  const value = useContext(ShopContext);
  if (!value) throw new Error("useShop must be used inside <ShopContext>");
  return value;
}
